/**
 * Report export pieces shared by the viewer and the "My exports" list: status
 * pill, progress bar, size text and the download button.
 *
 * Exports are generated by the worker in a fresh database snapshot, so a file
 * can differ from an earlier preview when data changed in between. Files are
 * private to their creator and expire (7 days).
 */
import { useState } from 'react'
import { useTranslation } from 'react-i18next'
import { Download } from 'lucide-react'
import Button from '@/components/ui/Button'
import StatusPill from '@/components/shared/StatusPill'
import { describeReportError, downloadReportExport } from '@/services/v2'
import type { ReportExport, ReportExportStatus } from '@/services/v2'
import { EXPORT_TONE } from './exportUtils'
import { formatCount } from '@/utils/v2/format'

export const ExportStatusPill = ({ status }: { status: ReportExportStatus }) => {
    const { t } = useTranslation()
    return (
        <StatusPill tone={EXPORT_TONE[status] || 'neutral'} size="row">
            <span data-testid="p4-export-status" data-status={status}>
                {t(`p4.status.${status}`, { defaultValue: status })}
            </span>
        </StatusPill>
    )
}

/** Rows written of expected, with a bar. Unknown expected stays unknown. */
export const ExportProgress = ({ exp }: { exp: ReportExport }) => {
    const { t } = useTranslation()
    const pct = Math.max(0, Math.min(100, exp.progress.percent || 0))
    return (
        <div className="min-w-[160px]" data-testid="p4-export-progress" data-percent={pct}>
            <div className="h-1.5 w-full overflow-hidden rounded-pill bg-gray-200 dark:bg-night-raised">
                <div className="h-full rounded-pill bg-azure-500 transition-[width] duration-200" style={{ width: `${pct}%` }} />
            </div>
            <div className="mt-1 text-[11.5px] text-gray-600 tabular-nums" dir="ltr">
                {exp.progress.rows_expected === null
                    ? t('p4.export.rowsWrittenOnly', { n: formatCount(exp.progress.rows_written) })
                    : t('p4.export.rowsWritten', {
                          n: formatCount(exp.progress.rows_written),
                          of: formatCount(exp.progress.rows_expected),
                      })}{' '}
                · {pct.toFixed(0)}%
            </div>
        </div>
    )
}

/** Downloads a succeeded export; the API rechecks the creator and the report key. */
export const DownloadButton = ({ exp, size = 'sm' }: { exp: ReportExport; size?: 'xs' | 'sm' }) => {
    const { t } = useTranslation()
    const [busy, setBusy] = useState(false)
    const [error, setError] = useState<unknown>(null)
    if (!exp.actions?.download) return null
    return (
        <span className="inline-flex flex-col items-start">
            <Button
                size={size}
                variant="solid"
                loading={busy}
                icon={<Download size={14} />}
                data-testid="p4-export-download"
                data-export={exp.id}
                onClick={async () => {
                    setBusy(true)
                    setError(null)
                    try {
                        await downloadReportExport(exp)
                    } catch (e) {
                        setError(e)
                    } finally {
                        setBusy(false)
                    }
                }}
            >
                {t('p4.export.download')}
            </Button>
            {error ? (
                <span role="alert" className="mt-1 text-[12px] text-danger">
                    {describeReportError(error, t)}
                </span>
            ) : null}
        </span>
    )
}
